var match = src.match(/"images":\s*(\[[^\]]*?\])/);
var data = [];
if (match) {
    var arrStr = match[1];
    try {
        data = JSON.parse(arrStr.replace(/'/g, '"'));
    } catch (e) {
        data = eval(arrStr);
    }
}
var options = {
    "headers": {
        "User-Agent": "Mozilla/5.0 (Linux; Android 15; V2243A Build/AP3A.240905.015.A2) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/142.0.7444.102 Mobile Safari/537.36",
        "Referer": "", 
        "x-requested-with": "XBrowser",
        "Cache-Control": "max-age=0" 
    }
};
var imgTags = data.map(item => {
    const imgUrl = `https://cdn.favcomic.net/file/e-media/image${item}`;
    options.headers.Referer = imgUrl; 
    const h = JSON.stringify(options);
    return `<img src="${imgUrl},${h}">`;
}).join('\n');
imgTags;

